  3→description: >
  4→  Complete TypeScript API reference for all SpreadsheetApp, Spreadsheet, Sheet, Range, PivotTable,
  5→  EmbeddedChart, Filter, Utility, and related interfaces available in SheetAgent scripts.
  6→  Read before any `run_command` script that uses APIs you are unsure about, or when you need to
  7→  verify exact method signatures, parameter types, or return shapes. You may ONLY use APIs listed
  8→  here (or in another reference file you have read). Do NOT guess API names from memory.
  9→  Covers: SpreadsheetApp globals / Spreadsheet / Sheet / Range /
 10→  EmbeddedChart / Filter / Utility / BorderSide / TableInfo / ConditionalFormat
 11→  interfaces / ProtectRange interfaces (CLOUD_AGENT only). The PivotTable class and
 12→  PivotTableDetailData typings live in the sheet-pivot-tables reference; this file keeps only
 13→  the Sheet/Range pivot method signatures and PivotTableObjectInfoData. The chart-type contract —
 14→  the ChartType enum values, ChartOptions and ChartTextStyle type shapes — lives in the
 15→  charts-visual reference; this file keeps the Sheet chart method signatures (newChart /
 16→  insertChart / removeChart / getCharts), the EmbeddedChart class, and ChartObjectInfoData.
 17→---
 18→
 19→# Sheet API Reference — Complete TypeScript Declarations
 20→
 21→> **You may ONLY use the APIs listed below.** Do not guess API names from memory. If an API is not listed here, treat it as unavailable. Calling an undocumented API throws a `TypeError` that aborts the whole script — the message names a working alternative when one exists, so read it before retrying. If the required API does not exist, use JavaScript logic with existing APIs to achieve the goal (e.g., sort data in a JS array then write back with `setValues`). Do NOT guess or invent API methods.
 22→
 23→## 1. API Reference
 24→
 25→```typescript
 26→declare global {
 27→  var SpreadsheetApp: {
 28→    getActiveSpreadsheet(): Spreadsheet;
 29→    getActiveSheet(): Sheet;
 30→    getActiveRange(): Range;
 31→
 32→    Dimension: {
 33→      ROWS: "ROWS";
 34→      COLUMNS: "COLUMNS";
 35→    };
 36→    BorderStyle: {
 37→      DOTTED: "DOTTED";
 38→      DASHED: "DASHED";
 39→      SOLID: "SOLID";
 40→      SOLID_MEDIUM: "SOLID_MEDIUM";
 41→      SOLID_THICK: "SOLID_THICK";
 42→      DOUBLE: "DOUBLE";
 43→      /** Hairline — thinner than SOLID. Not a standard Apps-Script value. */
 44→      HAIR: "HAIR";
 45→    };
 46→    // ChartType — accepted `chartType` string values for sheet.newChart(...).
 47→    // Values + ChartOptions/ChartTextStyle shapes and styling rules live in charts-visual.
 48→    ChartType: { /* values: see charts-visual */ };
 49→  };
 50→
 51→  class Spreadsheet {
 52→    getActiveSheet(): Sheet;
 53→    getActiveRange(): Range;
 54→    getSheetById(sheetId: string): Sheet;
 55→    getSheetByName(name: string): Sheet | null;
 56→    getSheets(): Sheet[];
 57→    insertSheet(): Sheet;
 58→    insertSheet(sheetIndex: number): Sheet;
 59→    insertSheet(sheetName: string): Sheet;
 60→    insertSheet(sheetName: string, sheetIndex: number): Sheet;
 61→    deleteSheet(sheet: Sheet): void;
 62→    moveActiveSheet(pos: number): void;
 63→    moveSheet(srcIndex: number, desIndex: number): void;
 64→    // To duplicate a worksheet, call sheet.copyTo(newName) on the Sheet itself —
 65→    // Spreadsheet has no copySheet().
 66→  }
 67→
 68→  class Sheet {
 69→    getName(): string;
 70→    getSheetId(): string;
 71→    /** 1-based position of this worksheet in the workbook. */
 72→    getIndex(): number;
 73→
 74→    /** GRID SIZE — how many rows/columns this sheet HAS (e.g. 1000 x 26 on a new
 75→     *  sheet, whether or not anything is written there). */
 76→    getMaxRows(): number;
 77→    getMaxColumns(): number;
 78→    /** USED RANGE — the last row/column that actually HAS CONTENT; 0 on an empty
 79→     *  sheet. This is what you want for "read all the data" and for
 80→     *  "append after the existing rows":
 81→     *    sheet.getRange(1, 1, sheet.getLastRow(), sheet.getLastColumn()).getValues()
 82→     *    sheet.getRange(sheet.getLastRow() + 1, 1, n, m).setValues(rows)
 83→     *  The one-liner above is only safe for SMALL sheets — a single read is capped
 84→     *  at 24 blocks (~12000 rows of one column) and throws above that.
 85→     *  See "Reading large ranges" below before reading a tall sheet.
 86→     *  Do NOT confuse the two: on a fresh 1000-row sheet holding 3 rows of data,
 87→     *  getMaxRows() is 1000 and getLastRow() is 3. */
 88→    getLastRow(): number;
 89→    getLastColumn(): number;
 90→    /** Rename this worksheet (name: up to 31 chars). This is the ONLY way to rename —
 91→     *  do NOT create a new sheet and delete the old one (that also fails when the file
 92→     *  has a single visible sheet). Chainable: returns this sheet. */
 93→    setName(name: string): Sheet;
 94→    /** Duplicate this worksheet; newName is optional (max 31 chars).
 95→     *  NOT GAS-compatible: unlike Apps Script this takes the new sheet's NAME (not a
 96→     *  Spreadsheet) and returns the NEW sheet's id (a string), not a Sheet — so
 97→     *  `sheet.copyTo(ss).setName(x)` throws. Pass the id to
 98→     *  `SpreadsheetApp.getActiveSpreadsheet().getSheetById(id)` to get the Sheet object.
 99→     *  Note: this is a method on Sheet, NOT `spreadsheet.copySheet(sheet, name)`. */
100→    copyTo(newName?: string): string;
101→
102→    getRange(a1Notation: string): Range;
103→    getRange(row: number, col: number): Range;
104→    getRange(row: number, col: number, numRows: number, numCols: number): Range;
105→    getDataRange(): Range;
106→    getActiveRange(): Range;
107→
108→    /** Read the merged regions of this sheet. This is how you inspect merges —
109→     *  there is no other way. All four optional params are 1-based and default to
110→     *  the whole sheet; a merge that merely OVERLAPS the queried box is included.
111→     *  Returns Range objects — chain .getA1Notation() / .breakApart() / .getValue(),
112→     *  or .getRow() / .getColumn() / .getNumRows() / .getNumColumns() for plain
113→     *  coordinates. getMerges() is an alias of getMergedRanges().
114→     *  Example: for (const r of sheet.getMergedRanges()) r.breakApart(); */
115→    getMergedRanges(startRow?: number, startCol?: number, numRows?: number, numCols?: number): Range[];
116→    getMerges(startRow?: number, startCol?: number, numRows?: number, numCols?: number): Range[];
117→
118→    /** Clear the WHOLE worksheet: clear() erases content and styling,
119→     *  clearContents() erases content only. To clear part of a sheet, use
120→     *  `sheet.getRange(...).clear()` / `.clearContent()` instead.
121→     *  Chainable: returns this sheet. */
122→    clear(): Sheet;
123→    clearContents(): Sheet;
124→
125→    /** Read the FULL configuration of an existing pivot table — the ONLY way to
126→     *  inspect one (PivotTable is write-only). Return shape PivotTableDetailData and
127→     *  the full inspect guidance live in the **sheet-pivot-tables** reference. */
128→    getPivotTableDetail(pivotTableId?: string, pivotTableName?: string): PivotTableDetailData;
129→    getObjectList(objectTypes?: string[], namePattern?: string): SheetObjectData[];
130→    /** Hydrate an existing pivot table by id (or name) into a pre-populated PivotTable
131→     *  instance for modification (then add*/set* → update() to commit). Use this — NOT
132→     *  createPivotTable with the same id. Modify-vs-rebuild pattern: sheet-pivot-tables. */
133→    getPivotTable(pivotTableIdOrName: string): PivotTable;
134→
135→    insertRows(row: number, numRows?: number): void;
136→    deleteRow(row: number): void;
137→    deleteRows(row: number, numRows: number): void;
138→    /** Move `numRows` rows starting at `startRow` so they land before `destinationRow` (all 1-based). */
139→    moveRows(startRow: number, numRows: number, destinationRow: number): void;
140→    /** Move `numColumns` columns starting at `startColumn` so they land before `destinationColumn` (all 1-based). */
141→    moveColumns(startColumn: number, numColumns: number, destinationColumn: number): void;
142→
143→    /** Row height APIs — unit: pixels (px). Both parameters and return values are in pixels. */
144→    getRowHeight(row: number): number;
145→    setRowHeight(row: number, height: number): void;
146→    setRowHeights(startRow: number, numRows: number, height: number): void;
147→    setRowHeightsForced(startRow: number, numRows: number, height: number): void;
148→
149→    insertColumns(col: number, numCols?: number): void;
150→    deleteColumn(col: number): void;
151→    deleteColumns(col: number, numCols: number): void;
152→    /** Column width APIs — unit: pixels (px). Both parameters and return values are in pixels. */
153→    getColumnWidth(col: number): number;
154→    setColumnWidth(col: number, width: number): void;
155→    setColumnWidths(startCol: number, numCols: number, width: number): void;
156→
157→    /** Freeze top N rows (0 = unfreeze rows, keeps column freeze). */
158→    setFrozenRows(rows: number): void;
159→    /** Freeze left N columns (0 = unfreeze columns, keeps row freeze). */
160→    setFrozenColumns(columns: number): void;
161→
162→    /** Hide / show rows, columns and sheet tab. Indexes are 1-based; data is preserved (UI-only). */
163→    hideRow(rowIndex: number): Sheet;
164→    hideRows(rowIndex: number, numRows?: number): Sheet;
165→    showRows(rowIndex: number, numRows?: number): Sheet;
166→    unhideRow(rowIndex: number): Sheet;
167→    hideColumn(columnIndex: number): Sheet;
168→    hideColumns(columnIndex: number, numColumns?: number): Sheet;
169→    showColumns(columnIndex: number, numColumns?: number): Sheet;
170→    unhideColumn(columnIndex: number): Sheet;
171→    hideSheet(): Sheet;
172→    // Custom sheet views (a.k.a. FILTER VIEWS): a personal view state that does
173→    // NOT affect what collaborators see. Different from createFilter(), which
174→    // sets the sheet's single shared filter that everyone sees.
175→    // Excel has no equivalent — this is closer to Google Sheets' filter views.
176→    // Views have NO name: `guid` is the only handle for switching/removing one,
177→    // so capture the value returned by addCustomSheetView — or recover a lost
178→    // guid with getCustomSheetViews().
179→    // columns: { col (0-based), visibleValues } — empty visibleValues = don't filter.
180→    // Range bounds are 1-based inclusive; give all four or none.
181→    // Online documents only (NOT available in the local editor).
182→    // ⚠️ Never use createFilter() as a stand-in: it changes the SHARED filter that
183→    // every collaborator sees — a different semantic, not a weaker version of this.
184→    getCustomSheetViews(): { guid: string; range: string; columns: { col: number; visibleValues: string[] }[] }[];   // list existing views; also recovers a lost guid
185→    addCustomSheetView(options?: {
186→      startRow?: number; startCol?: number; endRow?: number; endCol?: number;
187→      columns?: { col: number; visibleValues: string[] }[];
188→    }): string;   // returns the new view's guid
189→    removeCustomSheetView(guid: string): Sheet;   // removes only the personal view state
190→    showSheet(): Sheet;
191→    // Show/hide this sheet's GRIDLINES — the light grey cell boundaries drawn by
192→    // default across the whole sheet. Hiding them gives a clean canvas (reports, covers).
193→    // NOT the same as cell borders: this never affects borders set via Range.setBorder
194→    // or style APIs. Local editor only (not available in remote/cloud mode).
195→    setGridLinesVisible(visible: boolean): Sheet;
196→    hideGridLines(): Sheet;   // alias of setGridLinesVisible(false)
197→    showGridLines(): Sheet;   // alias of setGridLinesVisible(true)
198→    isSheetHidden(): boolean;
199→
200→    newChart(
201→      drawingId: string,
202→      chartType: string,   // value list incl. combo presets: see charts-visual
203→      dataRange: Range,
204→      anchorRow: number, anchorCol: number,   // 0-based; -1, -1 = let newChart pick (see charts-create)
205→      offsetX: number, offsetY: number,
206→      width: number, height: number,          // default 600, 375
207→      options?: ChartOptions,
208→    ): EmbeddedChart;
209→    /** Compatibility no-op: chart is already inserted at newChart() time. */
210→    insertChart(chart: EmbeddedChart): void;
211→    // Delete: sheet.removeChart(chartId). Id lookup + reuse pitfalls: charts-delete.
212→    removeChart(chartId: string): void;
213→    // Insert an image at the specified cell position. row and col are 1-based.
214→    // imageData: base64 encoded image data or data URI (e.g. "data:image/png;base64,...")
215→    insertImage(row: number, col: number, imageData: string): void;
216→    // Insert a FLOATING image: a drawing object anchored to a cell but laid out
217→    // independently of the grid (it does NOT scale with that cell's row height /
218→    // column width). Use insertImage above when the image should live inside the cell.
219→    // drawingId must be unique in the workbook; it is the id getObjectList reports
220→    // (object_type === "float_image") and the id removeImage takes.
221→    // imageData: local absolute path or data URI. Remote http(s) URLs are NOT supported.
222→    // row/col are 1-based. offsets/width/height are pixels; width/height 0 = intrinsic size.
223→    // Local editor only (not available in remote/cloud mode).
224→    insertFloatImage(
225→      drawingId: string,
226→      row: number,
227→      col: number,
228→      imageData: string,
229→      options?: { horizontalOffset?: number; verticalOffset?: number; width?: number; height?: number; zIndex?: number },
230→    ): Sheet;
231→    // DELETE a floating image by its drawingId (look it up via getObjectList).
232→    // Local editor only (not available in remote/cloud mode).
233→    removeImage(drawingId: string): Sheet;
234→    // DELETE a cell image (image stored inside a cell) at the given 1-based row/col.
235→    // Local editor only (not available in remote/cloud mode).
236→    removeCellImage(row: number, col: number): Sheet;
237→    getCharts(): EmbeddedChart[];
238→    // columns[].col: 0-based column index, e.g., to filter the 4th column, pass col = 3
239→    // Creates the filter on this range. Call this FIRST before setColumnFilterCriteria —
240→    // a filter must exist for criteria to take effect. Throws if the sheet already has one.
241→    createFilter(range: Range): Filter;
242→    // Lazy handle to this sheet's filter. ALWAYS returns a non-null object even when no
243→    // filter exists, so a non-null return does NOT mean a filter is present. Prefer calling
244→    // createFilter() first (catch its "already has a filter" error) over getFilter() truthiness.
245→    getFilter(): Filter;
246→    getSheetName(): string;
247→
248→    // [CLOUD_AGENT only]
249→    // Mark a range as private (content masked from viewers); isUnset=true removes the marking. All params 1-based.
250→    setPrivateRange(startRow: number, startCol: number, numRows: number, numCols: number, isUnset?: boolean): void;
251→    // Set dropdown/multi-select validation on A1-notation ranges; type NONE removes the rule.
252→    setDataValidation(type: "LIST" | "MULTIPLE_LIST" | "NONE", ranges: string[], options?: Array<{ text: string; id?: string; text_color?: string; bg_color?: string }>): void;
253→    // Set dropdown/multi-select validation on whole columns; colIndexes are 0-based [{start,end}]; ignoreRows skips header rows.
254→    setDataValidationByColumns(type: "LIST" | "MULTIPLE_LIST" | "NONE", colIndexes: Array<{ start: number; end: number }>, ignoreRows?: number, options?: Array<{ text: string; id?: string; text_color?: string; bg_color?: string }>): void;
255→
256→    /** Add a new conditional format rule. Returns { cf_id } — save for update/remove. */
257→    addConditionalFormat(params: AddConditionalFormatParams): { cf_id: string };
258→    /** Query existing rules on this sheet (optionally filtered by range). Returns brief info only (cf_id/priority/ranges) — rule details are NOT returned. */
259→    getConditionalFormats(params: GetConditionalFormatsParams): { items: ConditionalFormatItem[] };
260→    /** Full replacement of an existing rule identified by cf_id. */
261→    updateConditionalFormat(params: UpdateConditionalFormatParams): void;
262→    /** Remove one rule by cf_id, or all rules when is_remove_all: true. */
263→    removeConditionalFormat(params: RemoveConditionalFormatParams): void;
264→
265→    // [CLOUD_AGENT only]
266→    /** Protect a range or the entire sheet. Returns { protect_range_id } — save for update/delete. */
267→    addProtectRange(params: AddProtectRangeParams): { protect_range_id: string };
268→    /** Change the protected range identified by protect_range_id. */
269→    updateProtectRange(params: UpdateProtectRangeParams): void;
270→    /** Remove a protection by protect_range_id. */
271→    deleteProtectRange(params: DeleteProtectRangeParams): void;
272→    /** List all protections on this sheet. */
273→    getProtectRanges(params: GetProtectRangesParams): { items: ProtectRangeItem[] };
274→  }
